  ('c8132bd5-23ee-5f36-b3f6-a75ef0c27ea3', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'aero-avante-18626', '18626', 'Aero Avante', 'エアロ アバンテ', 'Racing Mini 4WD', 'MA', 2012, 'Common', 'The flagship of the double-shaft MA chassis era. A low, wedge-shaped aero body that became the face of modern Mini 4WD racing.'),
  ('c7a440cc-dc07-5ecc-bae3-c2770dc8b66e', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'raikiri-18646', '18646', 'Raikiri', '雷牙', 'Racing Mini 4WD', 'AR', 2014, 'Common', 'Aggressive twin-blade styling on the rigid AR chassis. A staple of the modern competitive scene.'),
  ('d341ec22-c1f9-5a03-906d-444f8eee5401', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'dcr-01-18647', '18647', 'DCR-01', NULL, 'Racing Mini 4WD', 'MA', 2018, 'Common', 'Dual Ridge cowl developed with real aerodynamic testing. Successor lineage to the Avante family.'),
  ('68acb096-f01b-55b2-949b-a959279a2fa5', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'geo-glider-18093', '18093', 'Geo Glider', NULL, 'Racing Mini 4WD', 'FM-A', 2019, 'Uncommon', 'Front-motor FM-A chassis machine with a smooth gliding profile tuned for stability on technical sections.'),
  ('6f41e40f-a48e-509f-8602-dfd303e25795', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'shadow-shark-18095', '18095', 'Shadow Shark', NULL, 'Racing Mini 4WD', 'VZ', 2020, 'Uncommon', 'Sharp predatory silhouette debuting on the lightweight, responsive VZ chassis.'),
  ('51deac9c-f8a7-5eff-984f-968d6ad88659', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'festa-jaune-18641', '18641', 'Festa Jaune', NULL, 'Racing Mini 4WD', 'AR', 2013, 'Uncommon', 'Bright competition body on the AR chassis, popular for its clean lines and rigidity.'),
  ('9793fbe8-dcf7-51c9-9f45-185194a0bc92', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'neo-tridagger-zmc-19434', '19434', 'Neo-Tridagger ZMC', 'ネオトライダガー ZMC', 'Super Mini 4WD', 'Super II', 1998, 'Rare', 'The ZMC ''Zero Material Carbon'' hero machine. A fan favourite reissued for the modern Super II chassis.'),
  ('fa551244-1a12-54ec-b937-ad1b5603e8bb', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'magnum-saber-19401', '19401', 'Magnum Saber', 'マグナムセイバー', 'Fully Cowled', 'Super 1', 1994, 'Rare', 'Go Seiba''s first machine and the icon that launched the Fully Cowled boom of the 90s.'),
  ('896cc70e-3048-594d-9389-cb9808a5ad53', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'sonic-saber-19402', '19402', 'Sonic Saber', 'ソニックセイバー', 'Fully Cowled', 'Super 1', 1994, 'Rare', 'Retsu Seiba''s counterpart to the Magnum. Sleek blue styling built for cornering.'),
  ('f603ed6f-e601-5372-9fe7-6fd1034b6065', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'victory-magnum-19404', '19404', 'Victory Magnum', 'ビクトリーマグナム', 'Fully Cowled', 'Super 1', 1995, 'Uncommon', 'The Magnum''s evolution with a more aggressive cowl. A defining silhouette of the series.'),
  ('53791485-2948-5176-8acb-2ec947eafc51', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'cyclone-magnum-19425', '19425', 'Cyclone Magnum', 'サイクロンマグナム', 'Fully Cowled', 'Super TZ', 1996, 'Uncommon', 'Twin-intake cowl on the high-rigidity Super TZ chassis. One of the most beloved Magnum forms.'),
  ('a66d871c-00b1-56e5-9bc4-1621ea1729b2', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'beat-magnum-19426', '19426', 'Beat Magnum', 'ビートマグナム', 'Fully Cowled', 'Super TZ', 1997, 'Rare', 'The final Magnum of the original manga arc. Iconic red-and-white split cowl.'),
  ('dee35418-283b-5603-889b-b3eb2d68eea5', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'hurricane-sonic-19424', '19424', 'Hurricane Sonic', 'ハリケーンソニック', 'Fully Cowled', 'Super TZ', 1996, 'Uncommon', 'Sonic lineage''s high-speed form with sweeping intakes on the Super TZ chassis.'),
  ('da28c703-24ef-5ebd-a952-87346735dc7e', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'buster-sonic-19430', '19430', 'Buster Sonic', 'バスターソニック', 'Fully Cowled', 'Super TZ', 1997, 'Rare', 'The last Sonic of the arc, paired with the Beat Magnum in the series finale.'),
  ('82b478fd-21dd-5c93-82fb-bf50461a107d', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'avante-18709', '18709', 'Avante', 'アバンテ', 'Avante', 'Super II', 1988, 'Uncommon', 'The original wedge that started the Avante dynasty, reissued for the Super II chassis.'),
  ('6dcb6511-5277-561f-a880-95ef828ce44f', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'avante-mk-ii-18710', '18710', 'Avante Mk.II', 'アバンテ Mk.II', 'Avante', 'Zero', 1990, 'Very Rare', 'The Zero-chassis evolution of the Avante. A vintage grail for serious collectors.'),
  ('dcd372ac-5ad2-5a70-ae48-f1c4a6d6de4a', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'super-avante-18716', '18716', 'Super Avante', 'スーパーアバンテ', 'Avante', 'VZ', 2020, 'Common', 'A modern reinterpretation of the Avante line on the lightweight VZ chassis.'),
  ('a00d2b12-6a67-56ee-8db5-392eaf86d5c7', 'cd755fcb-2bc5-5975-8ec0-f45e7df891cc', '382feca9-48e9-5144-a92d-41f77fb7e438', 'vanguard-sonic-18725', '18725', 'Vanguard Sonic', 'バンガードソニック', 'Let''s & Go', 'Super II', 1996, 'Uncommon', 'MAX GP hero machine reissued on Super II. Smooth, purposeful racing body.'),
